/* ===== Аня, 5 класс. Математика — по учебнику Виленкина, Чеснокова, Шварцбурда, Жохова (1990) ===== */
const FR = (a, b) => `${a}/${b}`;
/* Числовой вариант, который должен остаться кнопкой с вариантами автора: «чистые» числа genTasks превращает в N
   и подставляет свои соседние числа (тогда в «Какое число простое?» оказывается три простых). Неразрывный пробел в конце не виден. */
const NK = x => String(x) + ' ';
function NC(q, a, w, e, f){ f = f || (x => U.big(x)); const A = f(a), ws = [];
  for (const x of w) { if (x == null || !isFinite(x) || x < 0 || Math.abs(x - a) < 1e-9) continue; const s = f(x); if (s !== A && !ws.includes(s)) ws.push(s); }
  return C(q, NK(A), ws.map(NK), e); }
/* Округление натурального n до k (10, 100, 1000): варианты — округлил не в ту сторону, не до того разряда */
function roundNC(q, n, k, e){ const a = Math.round(n / k) * k, dn = Math.floor(n / k) * k;
  return NC(q, a, [a === dn ? dn + k : dn, Math.round(n / (k / 10)) * (k / 10), Math.round(n / (k * 10)) * (k * 10), a + k, a - k, a + 2 * k], e); }
/* Округление десятичной дроби n/10^s до d знаков после запятой (ответ пишем с нужным числом знаков: 2,96 ≈ 3,0) */
function roundDC(q, n, s, d, e){ const k = 10 ** (s - d), a = Math.round(n / k), f = v => (v / 10 ** d).toFixed(d).replace('.', ','), A = f(a), val = x => +x.replace(',', '.');
  const other = d > 0 ? (Math.round(n / 10 ** (s - d + 1)) / 10 ** (d - 1)).toFixed(d - 1).replace('.', ',') : (Math.round(n / 10 ** (s - 1)) / 10).toFixed(1).replace('.', ',');
  const w = []; for (const x of [f(a * k > n ? a - 1 : a + 1), other, f(a * k > n ? a + 1 : a - 1), f(a + 2), f(a + 10)]) if (Math.abs(val(x) - val(A)) > 1e-9 && !w.includes(x)) w.push(x);
  return C(q, NK(A), w.slice(0, 3).map(NK), e); }
